        /// to 100.
        /// </summary>
        [Newtonsoft.Json.JsonPropertyAttribute("enforcingConsecutiveGatewayFailure")]
        public virtual System.Nullable<int> EnforcingConsecutiveGatewayFailure { get; set; }

        /// <summary>
        /// The percentage chance that a backend endpoint will be ejected when an outlier status is detected through
        /// success rate statistics. This setting can be used to disable ejection or to ramp it up slowly. Defaults to
        /// 100.  Not supported when the backend service uses Serverless NEG.
        /// </summary>
        [Newtonsoft.Json.JsonPropertyAttribute("enforcingSuccessRate")]
        public virtual System.Nullable<int> EnforcingSuccessRate { get; set; }

